import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"3、【屯】 震下坎上","description":"周易尚氏學 - 3、【屯】 震下坎上","frontmatter":{"title":"3、【屯】 震下坎上","description":"周易尚氏學 - 3、【屯】 震下坎上"},"headers":[],"relativePath":"classics/shangshi/008.md","filePath":"classics/shangshi/008.md"}'),s={name:"classics/shangshi/008.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_3、【屯】-震下坎上" tabindex="-1">3、【屯】 震下坎上 <a class="header-anchor" href="#_3、【屯】-震下坎上" aria-label="Permalink to “3、【屯】 震下坎上”">​</a></h1><p>上坎為險。下震為動。動乎險中。故名曰屯。屯難也。止也。諸家皆以乾通坤為元亨。三之正成既濟為利貞。按以乾通坤為元亨。初五得位。乾元以通是也。以三之正成既濟。為利貞非也。利貞者利於貞定也。勿用有攸往。申其義也。端木國瑚謂遇春夏卦。即曰元亨。秋冬卦即曰利貞。易本以時為主。說頗勝於舊解。屯由震春以至坎冬。一年氣備。故曰元亨又曰利貞。乾初勿用。往遇險。故曰勿用有攸往。侯君也。主也。震為君。初臨萬民。五居尊位。故曰利建侯。</p><p>彖曰。屯。剛柔始交而難生。動乎險中。大亨貞。雷雨之動滿盈。天造草昧。宜建侯而不寧。</p><p>始交為初五也。前乾坤二卦。皆純陽純陰莫能交。屯下震以乾交坤初。上坎以乾交坤中。以其次純乾純坤之後。剛柔雜始見。故曰始交。難謂坎也。蹇傳雲蹇難也。即指上坎。動而遇險。故曰難生。下雷上雨。坤為多故曰滿盈。造始也。草雜亂。昧冥昧。坤為茅茹為亂。故曰草。地黑故曰昧。易林艮之晉雲。釜甑草土。即以晉下坤為草。為釜。天造草昧者。言天地之運。始於草昧。故宜建侯於此時。使萬物有主也。諸家皆用虞翻說。謂剛柔始交。為坎二交初。如是穿鑿。又何不可謂革四交初。蓋虞氏不知始字承前兩卦乾坤而言。而以為指屯初二。故誤解若是。後閱道光間。卞斌周易通解。亦謂始交指初五。然則此義百年前已發之。</p><p>象曰。雲雷。屯。君子以經綸。</p><p>經綸據釋文。王弼本作經論。今本作經綸者。乃孔本也。因將王注亦改之矣。釋文又云。黃穎曰經綸匡濟也。本亦作倫。案釋名雲。綸倫也。為之有倫理也。論語正義引鄭玄雲。論者。綸也。理也。然則綸論論。字微異。義則同也。若以卦象言。震為言。初至五正反震。似論於易象較切。若正義所云劉表鄭玄作淪。似不合矣。</p><p>初九。盤桓。利居貞。利建侯。</p><p>盤桓。釋文雲族也。爾雅釋水鉤盤。郭注水曲如鉤。流盤桓不直前也。禹貢西傾因桓是來。注。桓隴皈名。其道盤旋。曲而上旋。即不能直前也。盤盤通。釋文雲。本亦作盤。馬又作盤。又或作般。皆以音同通用。外坎故利居貞不動。震為主。建侯則坤民有主。故利。</p><h3 id="象曰。雖盤桓。志行正也。以貴下賤。大得民也。" tabindex="-1">象曰。雖盤桓。志行正也。以貴下賤。大得民也。 <a class="header-anchor" href="#象曰。雖盤桓。志行正也。以貴下賤。大得民也。" aria-label="Permalink to “象曰。雖盤桓。志行正也。以貴下賤。大得民也。”">​</a></h3><p>坤為民。陰賤陽貴。陽在下。故曰以貴下賤。陽為大。初陽臨群陰。故曰大得民。</p><p>六二。屯如邅。乘馬班如。匪寇婚媾。女子貞不字。十年乃字。</p><p>陰遇陰得敵。故屯邅不進。釋文雲。邅。馬行不進之貌。班。子夏傳相牽不進兒。鄭作般。般盤同。亦盤桓不進也。又震為馬。坤坎皆為馬。馬多故曰班如。言行列不前也。吳先生曰。漢書車班班。往河間。義同此也。五坎為寇。二與五應。故曰匪寇。曰婚媾。乃二前為三四所阻。下為初陽所牽。體又為坤。坤虛故不字。字妊育也。震為孕。左傳昭元年。武王邑姜方震太叔是也。故震為妊育。王引之力闢宋耿南仲朱子以字為許嫁之非。其說是也。今河北尚呼牝牛為字牛。義本此也。坤為年。數十。故曰十年乃字。言二五。應與雖難。然究為正應。久必合也。</p><h3 id="象曰。六二之難。乘剛也。十年乃字。反常也。" tabindex="-1">象曰。六二之難。乘剛也。十年乃字。反常也。 <a class="header-anchor" href="#象曰。六二之難。乘剛也。十年乃字。反常也。" aria-label="Permalink to “象曰。六二之難。乘剛也。十年乃字。反常也。”">​</a></h3><p>此難字與象傳難生難字不同。彼指坎。此謂乘剛字難也。說者多混而同之。非。乘剛勢逆。故字難。</p><p>六三。即鹿無虞。惟入於林中。君子幾。不如合。往吝。</p><p>鹿。虞翻王肅皆作麓。鹿麓古通。詩瞻彼旱鹿。周語作旱鹿。韋注鹿山足也。三為艮初。正山足也。即鹿者。言至山足而從禽也。即就也。虞備虞也。孟子曰。有不虞之譽。義同此也。言田獵而無備虞。焉能有禽。震為木。艮亦為木。故曰林中。坤虛故空人林中。幾者事之先見者也。捨去也。言君子見幾而去也。上無應故往吝。艮為君子。淮南子說此雲。夫施薄而望厚者。未之有也。又三國志陳琳傳。易稱即鹿無虞。夫微物尚不可欺。夫所謂欺。即無備虞也。王弼雲。雖見其禽而無其虞。徒人於林中。亦詁虞為備虞。乃孔疏忽謂虞為虞官。失王義矣。左傳隱五年。不備不虞。不可以師。正與此無虞義同。</p><h3 id="象曰。即鹿無虞。以從禽也。君子舍之。往吝。窮也。" tabindex="-1">象曰。即鹿無虞。以從禽也。君子舍之。往吝。窮也。 <a class="header-anchor" href="#象曰。即鹿無虞。以從禽也。君子舍之。往吝。窮也。" aria-label="Permalink to “象曰。即鹿無虞。以從禽也。君子舍之。往吝。窮也。”">​</a></h3><p>從禽義與即鹿同。吝遴古通。說文行難也。三無應得敵故行難。吝字初見。說文口部引作吝。雲恨惜也。◇部引又作遴。雲行難。愚以為凡言往吝者。宜從行難義。祇言吝者。宜從恨惜義。此曰往吝。即行難也。</p><p>六四。乘馬班如。求婚媾。往吉。無不利。</p><p>坎坤皆為馬。故亦曰班如。艮為求。四與初本為正應。婚媾而已。然必求者。以二三為阻也。知其阻而求之。故往吉也。四上承陽。下有應。故曰無不利。</p><h3 id="象曰。求而往。明也。" tabindex="-1">象曰。求而往。明也。 <a class="header-anchor" href="#象曰。求而往。明也。" aria-label="Permalink to “象曰。求而往。明也。”">​</a></h3><p>艮火故曰明。艮陽在上亦明。自艮火艮明象失傳。諸家皆以三變互離為明矣。豈知旅九三雲。焚其次。易林大壯之遁雲。火爛銷金。皆以艮為火。說詳焦氏易詁中。</p><p>九五。屯其膏。小貞吉。大貞兇。</p><p>坎水故曰膏，坎陷故屯其膏。蓋五雖下履重陰。然坤民三分之二。為初所有。四又應初。五雖君位。實無一民。故膏澤無所施也。小謂二。五應二。陰得陽應故吉。大謂五。五虛擁尊位。威柄下移。孤露無輔。故大貞兇。震為威。坤為柄。貞卜問也。諸家強以貞正說之。夫正而有大小。已不詞矣。大正而兇。益悖理矣。惠士奇知其不安。又以固為說。其不協與正無異也。</p><h3 id="象曰。屯其膏。施未光也。" tabindex="-1">象曰。屯其膏。施未光也。 <a class="header-anchor" href="#象曰。屯其膏。施未光也。" aria-label="Permalink to “象曰。屯其膏。施未光也。”">​</a></h3><p>坎為隱伏。故曰未光。</p><p>上六。乘馬班如。泣血漣如。</p><p>坎為血。坎水故曰漣如。詩衛風。泣涕漣漣。釋文。泣貌。坎憂懼。下無應。故有是象。</p><h3 id="象曰。泣血漣如。何可長也。" tabindex="-1">象曰。泣血漣如。何可長也。 <a class="header-anchor" href="#象曰。泣血漣如。何可長也。" aria-label="Permalink to “象曰。泣血漣如。何可長也。”">​</a></h3><p>上六居卦之極。故曰不長。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
